const MotionComp = motion.create("button")

const Button = React.forwardRef<HTMLButtonElement, ButtonProps>(({
  className,
  variant,
  color,
  size,
  radius,
  isIconOnly,
  asChild = false,
  isLoading = false,
  loadingContent,
  startContent,
  endContent,
  children,
  disabled,
  ...props
}, ref) => {
  if (asChild) {
    return (
      <Slot
        ref={ref}
        data-slot="button"
        className={cn(
          buttonVariants({ variant, size, color, radius, isIconOnly }),
          className
        )}
        {...props}
      >
        {children}
      </Slot>
    )
  }

  const spinnerSize = size === "sm" ? "size-3" : size === "lg" ? "size-5" : "size-4"

  return (
    <MotionComp
      ref={ref}
      data-slot="button"
      disabled={disabled || isLoading}
      aria-busy={isLoading}
      className={cn(
        buttonVariants({ variant, size, color, radius, isIconOnly }),
        "active:scale-100" // disable CSS tap scale since we use spring scaling
      )}
      whileTap={{ scale: 0.96 }}
      transition={{ type: "spring", stiffness: 500, damping: 25 }}
      {...(props as any)}
    >
      {isLoading ? (
        <>
          <ButtonSpinner className={spinnerSize} />
          {loadingContent ?? (!isIconOnly && children)}
        </>
      ) : (
        <>
          {startContent}
          {children}
          {endContent}
        </>
      )}
    </MotionComp>
  )
})
Button.displayName = "Button"

